+      padding: clamp(1.5rem, 4vw, 2.5rem);
+    }
+
+    .eyebrow {
+      margin: 0 0 0.75rem;
+      color: var(--primary);
+      font-size: 0.8rem;
+      font-weight: 700;
+      letter-spacing: 0.08em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2rem, 5vw, 3rem);
+      line-height: 1.05;
+      letter-spacing: -0.04em;
+    }
+
+    .intro {
+      margin: 1rem 0 2rem;
+      color: var(--muted);
+      font-size: 1rem;
+      line-height: 1.6;
+    }
+
+    form {
+      display: grid;
+      gap: 1.15rem;
+    }
+
+    .form-field {
+      display: grid;
+      gap: 0.45rem;
+    }
+
+    label {
+      font-size: 0.92rem;
+      font-weight: 700;
+    }
+
+    input {
+      width: 100%;
+      border: 1px solid var(--border);
+      border-radius: 0.9rem;
+      color: var(--text);
+      background: #ffffff;
+      font: inherit;
+      padding: 0.9rem 1rem;
+      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    input::placeholder {
+      color: #98a2b3;
+    }
+
+    input:focus {
+      border-color: var(--primary);
+      box-shadow: 0 0 0 0.25rem var(--focus);
+      outline: none;
+    }
+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.84rem;
+      line-height: 1.45;
+    }
+
+    button {
+      border: 0;
+      border-radius: 0.95rem;
+      color: #ffffff;
+      background: linear-gradient(135deg, var(--primary), #4f46e5);
+      cursor: pointer;
+      font: inherit;
+      font-weight: 800;
+      margin-top: 0.4rem;
+      padding: 1rem 1.25rem;
+      box-shadow: 0 0.85rem 1.8rem rgba(37, 99, 235, 0.28);
+      transition: background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
+    }
+
+    button:hover {
+      background: linear-gradient(135deg, var(--primary-dark), #4338ca);
+      box-shadow: 0 1rem 2rem rgba(37, 99, 235, 0.32);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 0.25rem solid var(--focus);
+      outline-offset: 0.2rem;
+    }
+
+    .success-message {
+      display: none;
+      margin: 1rem 0 0;
+      color: var(--success);
+      font-weight: 700;
+      line-height: 1.5;
+    }
+
+    .success-message.is-visible {
+      display: block;
+    }
+  </style>
+</head>
