   </style>
 </head>
 <body>
   <main>
     <section class="support-card" aria-labelledby="support-title">
       <p class="eyebrow">Support</p>
       <h1 id="support-title">How can we help?</h1>
       <p class="intro">
         Send our team your contact details and we will get back to you with the right support.
       </p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name</label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             placeholder="Jane Doe"
             required
           >
         </div>

         <div class="form-field">
           <label for="email">Email address</label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             placeholder="jane@example.com"
             required
           >
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span aria-hidden="true">(optional)</span></label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             placeholder="+1 (555) 123-4567"
             aria-describedby="phone-helper"
           >
           <p class="helper-text" id="phone-helper">Use an international format, for example +1 (555) 123-4567.</p>
         </div>

         <button type="submit">Contact support</button>
       </form>

       <p class="success-message" id="success-message" role="status" aria-live="polite">
         Thanks! Your support request has been received.
       </p>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const successMessage = document.querySelector("#success-message");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!form.checkValidity()) {
         form.reportValidity();
         successMessage.classList.remove("is-visible");
         return;
       }

       successMessage.classList.add("is-visible");
       form.reset();
     });
   </script>
 </body>
 </html>

